INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6987635, 1053872, 144271, '<td valign="top">Has a kaleidoscope effect that is really pretty</td>', 'Has a kaleidoscope effect that is really pretty', '2013-02-28 11:29:20.000000', NULL, 1),
(6987636, 1054196, 144271, '<td valign="top">Love the colors and the shape</td>', 'Love the colors and the shape', '2013-02-28 11:29:52.000000', NULL, 1),
(6987637, 1054382, 144271, '<td valign="top">I love the black and white and color reversal.</td>', 'I love the black and white and color reversal.', '2013-02-28 11:30:35.000000', NULL, 1),
(6987639, 1054106, 144271, '<td valign="top">Very freaky</td>', 'Very freaky', '2013-02-28 11:32:09.000000', NULL, 1),
(6987651, 1054386, 63218, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1046796" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_1046796.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_1046796.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_1046796.jpg"/></a> <br/><a href="//www.dpchallenge.com/forum.php?action=read&amp;FORUM_THREAD_ID=1171726&amp;highlight=flying%20pig&amp;page=1" rel="nofollow" target="_blank">The Flying Pig</a> HM<br/> <br/>This may have started out as an orchid, it has the tactile presence of a flower that seems to always survive any PP. It works as a symbolic bee made of flower petals, but it also has a simple beauty that lets me admire it free of real world associations. The soft grainy nonspecific BG sets it off beautifully. The blacks are rich &amp; the greys hold a lot of light.<br/> <br/>I get few chances to award Flying Pigs, thank you very much for posting this lively comp for me to admire.</td>', ' The Flying Pig HM This may have started out as an orchid, it has the tactile presence of a flower that seems to always survive any PP. It works as a symbolic bee made of flower petals, but it also has a simple beauty that lets me admire it free of real world associations. The soft grainy nonspecific BG sets it off beautifully. The blacks are rich & the greys hold a lot of light. I get few chances to award Flying Pigs, thank you very much for posting this lively comp for me to admire.', '2013-02-28 12:01:32.000000', NULL, 1),
(6987659, 1054298, 63218, '<td valign="top">The camera angle makes a strong contribution to the fascinating charm of this comp. I''ve never before seen a man-made structure haunted by a tree. What an idea. The clear light &amp; sharp focus add a quirky touch of reality to this hyper-real shot. Good work.</td>', 'The camera angle makes a strong contribution to the fascinating charm of this comp. I''ve never before seen a man-made structure haunted by a tree. What an idea. The clear light & sharp focus add a quirky touch of reality to this hyper-real shot. Good work.', '2013-02-28 12:10:47.000000', NULL, 1),
(6987662, 1054097, 63218, '<td valign="top">My first pick of the realistic ones, this is so charming...&amp; so wierdly unsettling.</td>', 'My first pick of the realistic ones, this is so charming...& so wierdly unsettling.', '2013-02-28 12:12:46.000000', NULL, 1),
(6987665, 1054324, 152656, '<td valign="top">At first glance I wasn''t that impressed, but after taking a closer look....Wow!<br/> <br/>I love that you kept the original view through the windshield.  It makes the scene that much more believable!<br/> <br/>Nice job!</td>', 'At first glance I wasn''t that impressed, but after taking a closer look....Wow! I love that you kept the original view through the windshield.  It makes the scene that much more believable! Nice job!', '2013-02-28 12:21:15.000000', NULL, 1),
(6987674, 1054311, 152656, '<td valign="top">I''m over half way through voting and this is the first picture I''ve seen where the lines of symmetry are angled rather than perfectly ''top to bottom'' or ''left to right''.<br/> <br/>Way to think outside the box!!</td>', 'I''m over half way through voting and this is the first picture I''ve seen where the lines of symmetry are angled rather than perfectly ''top to bottom'' or ''left to right''. Way to think outside the box!!', '2013-02-28 12:34:14.000000', NULL, 1),
(6987760, 1054064, 63218, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1046796" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_1046796.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_1046796.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/60000-64999/63218/120/Copyrighted_Image_Reuse_Prohibited_1046796.jpg"/></a> <br/><a href="//www.dpchallenge.com/forum.php?action=read&amp;FORUM_THREAD_ID=1171726&amp;highlight=flying%20pig&amp;page=1" rel="nofollow" target="_blank">The Flying Pig</a> HM<br/> <br/>Oh yes. Divine light. Angel wings. Pearly gates. All share these colors, this simple elegance. Well done! <br/> <br/>Thanks you for posting it. I don''t get to award a Flying Pig very often, so double thank you!</td>', ' The Flying Pig HM Oh yes. Divine light. Angel wings. Pearly gates. All share these colors, this simple elegance. Well done!  Thanks you for posting it. I don''t get to award a Flying Pig very often, so double thank you!', '2013-02-28 15:27:04.000000', NULL, 1),
